//! Port parsing that reproduces the C++ implementation's `std::stoi` behaviour.

/// Value `URL::port()` reports when the URL carries no usable port.
pub const NO_PORT: i32 = -1;

/// Largest value still accepted as a port; anything above becomes [`NO_PORT`].
const MAX_PORT: i64 = 65535;

/// Parses the text after the host's `:` exactly the way the C++ code does.
///
/// The original calls `std::stoi` inside a `try` block and rejects whatever
/// falls outside `0..=65535`, so this inherits `strtol`'s quirks: leading
/// whitespace and a `+`/`-` sign are consumed, parsing stops at the first
/// non-digit (`"80abc"` is 80), and a missing or out-of-range number -- which
/// would raise `invalid_argument`/`out_of_range` -- yields [`NO_PORT`].
pub fn parse_port(text: &str) -> i32 {
    let bytes = text.as_bytes();
    let mut i = 0;

    while i < bytes.len() && is_space(bytes[i]) {
        i += 1;
    }

    let negative = match bytes.get(i) {
        Some(b'+') => {
            i += 1;
            false
        }
        Some(b'-') => {
            i += 1;
            true
        }
        _ => false,
    };

    let first_digit = i;
    let mut value: i64 = 0;
    while let Some(&b) = bytes.get(i) {
        if !b.is_ascii_digit() {
            break;
        }
        // Once the number has outgrown a port there is no way back, so stop
        // accumulating instead of tracking a width `stoi` would have rejected.
        if value <= MAX_PORT {
            value = value * 10 + i64::from(b - b'0');
        }
        i += 1;
    }

    // No digits at all is `std::invalid_argument` on the C++ side.
    if i == first_digit {
        return NO_PORT;
    }

    if negative {
        value = -value;
    }

    if (0..=MAX_PORT).contains(&value) {
        value as i32
    } else {
        NO_PORT
    }
}

/// The set of bytes `strtol` treats as leading whitespace in the "C" locale.
fn is_space(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

