//! The `URL` type: splits a URL string into scheme, host, port, path, query.

use super::port::{parse_port, NO_PORT};

/// Marker that introduces an authority; without it the URL has no host.
const SCHEME_SEPARATOR: &str = "://";

/// A parsed URL, mirroring `url_parser::URL` from the C++ header.
///
/// Parsing happens once in [`Url::new`]; the accessors only hand back slices of
/// what was stored, just like the C++ getters returning `const std::string&`.
pub struct Url {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
}

impl Url {
    /// Splits `url` into its components.
    ///
    /// The order of the cuts is what gives the parser its observable
    /// behaviour, so it is preserved here: fragment, then query, then scheme,
    /// then the authority. Splitting the query *before* looking for `://` is
    /// why `/p?x=http://y` parses as path `/p` with the whole `x=http://y`
    /// left in the query rather than as a URL with scheme `/p?x=http`.
    pub fn new(url: &str) -> Self {
        let without_fragment = match url.find('#') {
            Some(i) => &url[..i],
            None => url,
        };

        let (before_query, query) = match without_fragment.find('?') {
            Some(i) => (&without_fragment[..i], &without_fragment[i + 1..]),
            None => (without_fragment, ""),
        };

        // No `://` means no authority: the remainder is entirely path, and
        // scheme/host stay empty. This is why `mailto:a@b` and `//host/p` both
        // come back as a bare path.
        let Some(separator) = before_query.find(SCHEME_SEPARATOR) else {
            return Self {
                scheme: String::new(),
                host: String::new(),
                port: NO_PORT,
                path: before_query.to_string(),
                query: query.to_string(),
            };
        };

        // Only the scheme is case-folded; the host keeps the spelling it came
        // with. Restricting this to ASCII leaves other bytes alone, matching
        // `std::tolower` in the "C" locale.
        let scheme = before_query[..separator].to_ascii_lowercase();
        let after_scheme = &before_query[separator + SCHEME_SEPARATOR.len()..];

        let (authority, path) = match after_scheme.find('/') {
            Some(i) => (&after_scheme[..i], &after_scheme[i..]),
            None => (after_scheme, ""),
        };

        // Userinfo is dropped at the first `@`, so `a@b@c.com` hosts at
        // `b@c.com`. A `@` later in the path is untouched because the
        // authority was already cut at the first `/`.
        let authority = match authority.find('@') {
            Some(i) => &authority[i + 1..],
            None => authority,
        };

        // The first `:` ends the host, which is why a bracketed IPv6 literal
        // splits mid-address instead of being recognised.
        let (host, port) = match authority.find(':') {
            Some(i) => (&authority[..i], parse_port(&authority[i + 1..])),
            None => (authority, NO_PORT),
        };

        Self {
            scheme,
            host: host.to_string(),
            port,
            path: path.to_string(),
            query: query.to_string(),
        }
    }

    /// Lowercased scheme, empty when the URL had no `://`.
    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    /// Host with userinfo and port removed.
    pub fn host(&self) -> &str {
        &self.host
    }

    /// Port, or `-1` when absent or not a value in `0..=65535`.
    pub fn port(&self) -> i32 {
        self.port
    }

    /// Path including its leading `/`, empty when the URL had none.
    pub fn path(&self) -> &str {
        &self.path
    }

    /// Query with the `?` stripped, empty when the URL had none.
    pub fn query(&self) -> &str {
        &self.query
    }
}

