//! Regression tests pinning the quirks observed in the C++ implementation.

use super::Url;

fn parts(url: &str) -> (String, String, i32, String, String) {
    let u = Url::new(url);
    (
        u.scheme().to_string(),
        u.host().to_string(),
        u.port(),
        u.path().to_string(),
        u.query().to_string(),
    )
}

/// Asserts the five components, keeping each case to a single readable line.
macro_rules! assert_parses {
    ($url:expr => $scheme:expr, $host:expr, $port:expr, $path:expr, $query:expr) => {
        assert_eq!(
            parts($url),
            (
                $scheme.to_string(),
                $host.to_string(),
                $port,
                $path.to_string(),
                $query.to_string()
            ),
            "parsing {:?}",
            $url
        );
    };
}

#[test]
fn documented_examples() {
    assert_parses!("http://example.com" => "http", "example.com", -1, "", "");
    assert_parses!("https://example.com" => "https", "example.com", -1, "", "");
    assert_parses!("http://localhost" => "http", "localhost", -1, "", "");
    assert_parses!("http://127.0.0.1" => "http", "127.0.0.1", -1, "", "");
    assert_parses!("http://example.com:8080" => "http", "example.com", 8080, "", "");
}

#[test]
fn full_url_splits_into_all_five_parts() {
    assert_parses!("http://example.com:8080/a/b?x=1&y=2" => "http", "example.com", 8080, "/a/b", "x=1&y=2");
}

#[test]
fn only_the_scheme_is_lowercased() {
    assert_parses!("HtTpS://Ex.COM:80/P?Q#F" => "https", "Ex.COM", 80, "/P", "Q");
}

#[test]
fn non_ascii_bytes_survive_the_scheme_fold() {
    assert_parses!("HTTPÄ://Ex.cÖm:80/P" => "httpÄ", "Ex.cÖm", 80, "/P", "");
}

#[test]
fn without_the_separator_everything_is_path() {
    // No "://" means no authority at all, not even a guessed host.
    assert_parses!("no-scheme.com/path" => "", "", -1, "no-scheme.com/path", "");
    assert_parses!("mailto:user@example.com" => "", "", -1, "mailto:user@example.com", "");
    assert_parses!("//example.com/path" => "", "", -1, "//example.com/path", "");
}

#[test]
fn separator_at_the_start_still_parses_an_authority() {
    assert_parses!("://ex.com/p" => "", "ex.com", -1, "/p", "");
}

#[test]
fn scheme_uses_the_first_separator_and_is_not_validated() {
    assert_parses!("a://b://c/d" => "a", "b", -1, "//c/d", "");
    assert_parses!("http:://ex.com/p" => "http:", "ex.com", -1, "/p", "");
    assert_parses!("ht tp://ex.com/p" => "ht tp", "ex.com", -1, "/p", "");
}

#[test]
fn query_is_split_before_the_scheme_is_looked_for() {
    // The "://" inside the query must not be mistaken for a scheme marker.
    assert_parses!("/path?x=http://y.com" => "", "", -1, "/path", "x=http://y.com");
    assert_parses!("?q=http://y.com" => "", "", -1, "", "q=http://y.com");
    // ...and the authority never sees the query either.
    assert_parses!("http://a?b?c" => "http", "a", -1, "", "b?c");
}

#[test]
fn fragment_is_stripped_before_everything_else() {
    assert_parses!("http://ex.com/path#frag?notquery" => "http", "ex.com", -1, "/path", "");
    assert_parses!("http://ex.com#f:8080" => "http", "ex.com", -1, "", "");
    assert_parses!("#http://a.com/p" => "", "", -1, "", "");
    assert_parses!("/p#x://y" => "", "", -1, "/p", "");
    assert_parses!("http://ex.com/p?q=#f" => "http", "ex.com", -1, "/p", "q=");
}

#[test]
fn userinfo_is_dropped_at_the_first_at_sign() {
    assert_parses!("http://user:pass@host/x" => "http", "host", -1, "/x", "");
    assert_parses!("http://a@b@c.com:80/x" => "http", "b@c.com", 80, "/x", "");
    assert_parses!("http://host@:80/x" => "http", "", 80, "/x", "");
    assert_parses!("http://h:80@x/p" => "http", "x", -1, "/p", "");
    // The authority ends at the first '/', so a later '@' is just path text.
    assert_parses!("http://host/path@foo" => "http", "host", -1, "/path@foo", "");
}

#[test]
fn host_ends_at_the_first_colon_so_ipv6_is_not_understood() {
    assert_parses!("http://[::1]:8080/v6" => "http", "[", -1, "/v6", "");
    assert_parses!("http://[2001:db8::1]/v6" => "http", "[2001", -1, "/v6", "");
